# ---------------- data.json ----------------
dp = os.path.join(BASE, "data.json")
data = json.load(open(dp, encoding="utf-8"))
assert data[-1]["date"] != TODAY, "今日已存在，终止"
data.append({
    "date": TODAY,
    "topic": TOPIC,
    "summary": SUMMARY,
    "file": "fs_%s.html" % TODAY,
})
data.sort(key=lambda r: r["date"])
json.dump(data, open(dp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("[2] data.json 追加至 %d 条，末条 = %s" % (len(data), data[-1]["date"]))

# ---------------- index.html = 当日卡片逐字节复制 ----------------
shutil.copyfile(fs_path, os.path.join(BASE, "index.html"))
print("[3] index.html = fs_%s.html（逐字节复制）" % TODAY)

# ---------------- content_bank.json 正则回填 ----------------
cbp = os.path.join(BASE, "content_bank.json")
cb = json.load(open(cbp, encoding="utf-8"))
secs = re.findall(r'<div class="section-content">(.*?)</div>', html, re.S)
summ = re.search(r'<div class="summary-content">(.*?)</div>', html, re.S).group(1)
assert len(secs) == 3, "section 抽取异常：%d" % len(secs)
if not any(e.get("topic") == TOPIC for e in cb):
    cb.append({
        "topic": TOPIC,
        "law_points": secs[0],
        "practice_scene": secs[1],
        "risk_alert": secs[2],
        "summary": summ,
    })
    json.dump(cb, open(cbp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("[4] content_bank.json -> %d 条" % len(cb))
